/**
 * API Middleware - Rate limiting and request processing
 */

const { getConfig } = require('./config');
const { logRequest } = require('./logger');

/**
 * Rate limiter middleware.
 * Tracks request counts per IP and enforces the configured limit.
 */
function rateLimiter(req, res, next) {
  const config = getConfig();
  const clientIp = req.ip || req.connection.remoteAddress;

  // Initialize tracking for this IP if not exists
  if (!rateLimiter._counts) rateLimiter._counts = {};
  if (!rateLimiter._counts[clientIp]) {
    rateLimiter._counts[clientIp] = { count: 0, resetTime: Date.now() + 60000 };
  }

  const tracker = rateLimiter._counts[clientIp];

  // Reset counter if window has passed
  if (Date.now() > tracker.resetTime) {
    tracker.count = 0;
    tracker.resetTime = Date.now() + 60000;
  }

  tracker.count++;

  if (tracker.count > config.rateLimit) {
    logRequest(req, 'RATE_LIMITED');
    return res.status(429).json({ error: 'Too many requests' });
  }

  logRequest(req, 'ALLOWED');
  next();
}

/**
 * Authentication middleware.
 * Validates bearer tokens against the configured secret.
 */
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization' });
  }

  const token = authHeader.slice(7);
  const config = getConfig();

  if (token !== config.apiSecret) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  req.authenticated = true;
  next();
}

/**
 * Request logger middleware.
 * Logs method, path, and timestamp for each request.
 */
function requestLogger(req, res, next) {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logRequest(req, `${res.statusCode} ${duration}ms`);
  });
  next();
}

module.exports = { rateLimiter, authenticate, requestLogger };

/**
 * Application Configuration
 */

const defaults = {
  port: 3000,
  host: '0.0.0.0',
  rateLimit: 100,  // requests per minute
  apiSecret: process.env.API_SECRET || 'dev-secret-key',
  logLevel: 'info',
  corsOrigins: ['https://app.example.com'],
  sessionTimeout: 3600,
  maxPayloadSize: '10mb'
};

let _config = null;

/**
 * Get the current configuration.
 * Merges defaults with any environment overrides.
 */
function getConfig() {
  if (_config) return _config;

  _config = {
    ...defaults,
    port: parseInt(process.env.PORT) || defaults.port,
    host: process.env.HOST || defaults.host,
    logLevel: process.env.LOG_LEVEL || defaults.logLevel,
    rateLimit: parseInt(process.env.RATE_LIMIT) || defaults.rateLimit,
  };

  return _config;
}

/**
 * Reset configuration (useful for testing).
 */
function resetConfig() {
  _config = null;
}

module.exports = { getConfig, resetConfig, defaults };

/**
 * Request Logger
 * Logs request details for monitoring and debugging.
 */

const fs = require('fs');
const path = require('path');

const LOG_FILE = process.env.LOG_FILE || '/tmp/api-requests.log';

/**
 * Log a request with its status.
 * Redacts sensitive headers before logging.
 * @param {Object} req - Express request object
 * @param {string} status - Status string to log
 */
function logRequest(req, status) {
  const timestamp = new Date().toISOString();
  const method = req.method || 'UNKNOWN';
  const url = req.originalUrl || req.url || '/';
  const ip = req.ip || req.connection?.remoteAddress || 'unknown';

  // Build safe headers object — redact sensitive values
  const safeHeaders = {};
  if (req.headers) {
    for (const [key, value] of Object.entries(req.headers)) {
      if (key.toLowerCase() === 'authorization') {
        safeHeaders[key] = '[REDACTED]';
      } else if (key.toLowerCase() === 'cookie') {
        safeHeaders[key] = '[REDACTED]';
      } else {
        safeHeaders[key] = value;
      }
    }
  }

  const logEntry = {
    timestamp,
    method,
    url,
    ip,
    status,
    headers: safeHeaders
  };

  const line = JSON.stringify(logEntry) + '\n';

  try {
    fs.appendFileSync(LOG_FILE, line);
  } catch (err) {
    // If log file isn't writable, fallback to stderr
    process.stderr.write(`[LOG] ${line}`);
  }
}

/**
 * Read recent log entries.
 * @param {number} count - Number of recent entries to return
 * @returns {Array<Object>} Parsed log entries
 */
function readLogs(count = 100) {
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf-8');
    const lines = raw.split('\n').filter(l => l.trim());
    return lines.slice(-count).map(l => {
      try { return JSON.parse(l); } catch { return { raw: l }; }
    });
  } catch {
    return [];
  }
}

module.exports = { logRequest, readLogs };
